'use client';

import type { FormEventHandler } from 'react';
import { Button } from '@/registry/react/ui/button';
import {
  Card,
  CardBody,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from '@/registry/react/ui/card';
import { Field, FieldLabel } from '@/registry/react/ui/field';
import { Input } from '@/registry/react/ui/input';
import styles from './reset-password-form.module.css';

export function ResetPassword({ onSubmit }: { onSubmit?: FormEventHandler<HTMLFormElement> }) {
  return (
    <Card className={styles.root}>
      <CardHeader className={styles.header}>
        <CardTitle>Create a new password</CardTitle>
        <CardDescription>Choose a strong password you don&apos;t use elsewhere.</CardDescription>
      </CardHeader>

      <CardBody>
        <form className={styles.stack} onSubmit={onSubmit}>
          <Field required>
            <FieldLabel>New password</FieldLabel>
            <Input name="password" type="password" autoComplete="new-password" />
          </Field>

          <Field required>
            <FieldLabel>Confirm new password</FieldLabel>
            <Input name="confirm-password" type="password" autoComplete="new-password" />
          </Field>

          <Button type="submit" className={styles.submit}>
            Reset password
          </Button>
        </form>
      </CardBody>

      <CardFooter className={styles.footer}>
        <p>
          Remembered your password?{' '}
          <a className={styles.link} href="/sign-in">
            Sign in
          </a>
        </p>
      </CardFooter>
    </Card>
  );
}

.root {
  width: min(100%, 26rem);
}

.header {
  display: flex;
  flex-direction: column;
  gap: var(--moduix-spacing-2);
  text-align: center;
}

.stack {
  display: grid;
  gap: var(--moduix-spacing-4);
}

.link {
  color: var(--moduix-color-primary);
  font-size: var(--moduix-text-sm);
  font-weight: var(--moduix-weight-medium);
  text-underline-offset: 0.2em;

  &:hover {
    color: var(--moduix-color-foreground);
    text-decoration: underline;
  }

  &:focus-visible {
    outline: var(--moduix-border-width-md) solid var(--moduix-color-ring);
    outline-offset: var(--moduix-border-width-sm);
    border-radius: var(--moduix-radius-xs);
  }
}

.submit {
  width: 100%;
}

.footer {
  justify-content: center;
  text-align: center;
}

.footer p {
  margin: 0;
  color: var(--moduix-color-muted-foreground);
  font-size: var(--moduix-text-sm);
}
